/**
 * ===================================================================
 * HELPER FUNCTIONS
 * ===================================================================
 */

async function fillForm(page: Page, data: Record<string, any>) {
  if (data.username !== undefined) {
    await page.fill('#username', String(data.username));
  }
  if (data.email !== undefined) {
    await page.fill('#email', String(data.email));
  }
  if (data.password !== undefined) {
    await page.fill('#password', String(data.password));
  }
  if (data.age !== undefined) {
    // Use evaluate to bypass browser validation for input[type=number]
    await page.evaluate((value) => {
      const input = document.querySelector('#age') as HTMLInputElement;
      if (input) input.value = value;
    }, String(data.age));
  }
  if (data.birthDate !== undefined) {
    // Use evaluate to bypass browser validation for input[type=date]
    await page.evaluate((value) => {
      const input = document.querySelector('#birthDate') as HTMLInputElement;
      if (input) input.value = value;
    }, String(data.birthDate));
  }
  if (data.role !== undefined) {
    await page.selectOption('#role', String(data.role));
  }
  if (data.config !== undefined) {
    await page.fill('#config', String(data.config));
  }
}

async function submitForm(page: Page): Promise<{ success: boolean; message?: string; issues?: string[] }> {
  const submitButton = page.locator('button[type="submit"]');
  
  const startTime = Date.now();
  await submitButton.click();
  
  // Wait for result
  await page.waitForSelector('.result-message', { timeout: 5000 });
  const elapsed = Date.now() - startTime;
  
  if (elapsed > PERFORMANCE_THRESHOLD_MS) {
    console.warn(`⚠️ Performance: Submit took ${elapsed}ms (threshold: ${PERFORMANCE_THRESHOLD_MS}ms)`);
  }
  
  const resultMessage = page.locator('.result-message');
  const isSuccess = await resultMessage.evaluate(el => el.classList.contains('ok'));
  const messageText = await resultMessage.locator('p').first().textContent();
  
  const issues: string[] = [];
  const issueItems = await resultMessage.locator('ul li').all();
  for (const item of issueItems) {
    const text = await item.textContent();
    if (text) issues.push(text);
  }
  
  return {
    success: isSuccess,
    message: messageText || undefined,
    issues: issues.length > 0 ? issues : undefined
  };
}

/**
 * ===================================================================
 * USERNAME FIELD - Heuristic Tests
 * ===================================================================
 */
test.describe('Username Field - Heuristic Testing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(FORM_URL);
  });

  test('should accept valid usernames', async ({ page }) => {
    for (const username of HeuristicInputs.username.valid) {
      const oracle = FormOracle.isValidUsername(username);
      
      await fillForm(page, {
        username,
        email: 'test@example.com',
        password: 'password123',
        role: 'User'
      });
      
      const result = await submitForm(page);
      
      if (oracle.valid && !result.success) {
        console.error(`❌ Oracle mismatch: "${username}" should be valid but got error:`, result.issues);
      }
      
      expect(result.success).toBe(oracle.valid);
      await page.reload();
    }
  });

  test('should reject invalid usernames', async ({ page }) => {
    for (const username of HeuristicInputs.username.invalid) {
      const oracle = FormOracle.isValidUsername(username);
      
      await fillForm(page, {
        username,
        email: 'test@example.com',
        password: 'password123',
        role: 'User'
      });
      
      const result = await submitForm(page);
      
      if (!oracle.valid && result.success) {
        console.error(`❌ Oracle mismatch: "${username}" should be invalid but passed`);
      }
      
      expect(result.success).toBe(oracle.valid);
      await page.reload();
    }
  });

  test('should handle username edge cases', async ({ page }) => {
    for (const username of HeuristicInputs.username.edge) {
      const oracle = FormOracle.isValidUsername(username);
      
      await fillForm(page, {
        username,
        email: 'test@example.com',
        password: 'password123',
        role: 'User'
      });
      
      const result = await submitForm(page);
      
      console.log(`📊 Edge case "${username.substring(0, 20)}...": Oracle=${oracle.valid}, Actual=${result.success}`);
      
      expect(result.success).toBe(oracle.valid);
      await page.reload();
    }
  });
});

